#!/usr/bin/env bash
# Convert Image — generated by scripts/build_installer.py
set -Eeuo pipefail
VERSION="3.0.0"
action=install
skip_deps=0
check_only=0

fail() { printf '\n[ERROR] %s\n' "$*" >&2; exit 1; }
trap 'printf "\n[ERROR] Gagal pada baris %s. Periksa pesan di atas.\n" "$LINENO" >&2' ERR

for option in "$@"; do
    case "$option" in
        --uninstall) action=uninstall ;;
        --no-deps) skip_deps=1 ;;
        --check) check_only=1 ;;
        --version) printf 'Convert Image %s\n' "$VERSION"; exit 0 ;;
        --help|-h)
            cat <<'HELP'
Convert Image
Penggunaan: bash install-image.sh [opsi]

  --check       Periksa dependensi tanpa memasang atau mengubah file
  --no-deps     Pasang file saja; dependensi tetap harus tersedia
  --uninstall   Hapus converter, launcher, dan menu milik pengguna ini
  --version     Tampilkan versi
  --help        Tampilkan bantuan

Jalankan sebagai pengguna desktop biasa, tanpa sudo di depan installer.
HELP
            exit 0 ;;
        *) fail "Opsi tidak dikenal: $option (lihat --help)" ;;
    esac
done

(( EUID != 0 )) || fail 'Jalankan sebagai pengguna desktop biasa, bukan root.'
[[ -x /usr/bin/python3 ]] || fail 'Python sistem tidak ditemukan: /usr/bin/python3'

printf '\nConvert Image v%s\n\n' "$VERSION"
if [[ "$action" == install ]]; then
    command -v nemo >/dev/null || fail 'Nemo tidak ditemukan. Gunakan Linux Mint Cinnamon / desktop dengan Nemo.'
    if (( skip_deps == 0 && check_only == 0 )); then
        command -v apt-get >/dev/null || fail 'Pemasangan otomatis memerlukan APT. Pasang dependensi manual, lalu gunakan --no-deps.'
        command -v sudo >/dev/null || fail 'sudo tidak tersedia.'
        # Mint calls this package python-nemo; Ubuntu/Debian use nemo-python.
        nemo_binding=python-nemo
        if [[ -r /etc/os-release ]]; then
            distro_id="$(. /etc/os-release; printf '%s' "${ID:-}")"
            [[ "$distro_id" == linuxmint ]] || nemo_binding=nemo-python
        fi
        packages=(python3 "$nemo_binding" python3-gi gir1.2-nemo-3.0 python3-pil python3-reportlab python3-pypdf libavif-bin zenity)
        missing=()
        for package in "${packages[@]}"; do
            if [[ "$(dpkg-query -W -f='${Status}' "$package" 2>/dev/null || true)" != 'install ok installed' ]]; then
                missing+=("$package")
            fi
        done
        if ((${#missing[@]})); then
            printf '[1/3] Memperbarui daftar paket...\n'
            if ! sudo apt-get update; then
                fail 'APT update gagal. Perbaiki repositori yang disebut pada output, lalu jalankan installer kembali. File aplikasi belum diubah.'
            fi
            printf '[1/3] Memasang dependensi: %s\n' "${missing[*]}"
            sudo apt-get install -y "${missing[@]}"
        else
            printf '[1/3] Paket yang diperlukan sudah terpasang.\n'
        fi
    fi
    printf '[2/3] Memeriksa dependensi...\n'
    /usr/bin/python3 - <<'CHECK_PY'
import shutil
import sys
import os
from pathlib import Path
vendor = Path(os.environ.get('XDG_DATA_HOME', Path.home() / '.local/share')) / 'img2avif/vendor'
if vendor.is_dir():
    sys.path.insert(0, str(vendor))
errors = []
for module in ('reportlab', 'pypdf'):
    try:
        __import__(module)
    except ImportError as exc:
        errors.append('Dependensi PDF: ' + str(exc))
for program in ('nemo', 'avifenc', 'avifdec', 'zenity'):
    if not shutil.which(program):
        errors.append('Program belum tersedia: ' + program)
try:
    import gi
    gi.require_version('Nemo', '3.0')
    from gi.repository import Nemo
except (ImportError, ValueError) as exc:
    errors.append('Binding Nemo / GI: ' + str(exc))
try:
    from PIL import Image, ImageCms, features
    if not features.check('jpg'):
        errors.append('Pillow belum mendukung JPEG')
    if not features.check('webp'):
        errors.append('Pillow belum mendukung WebP')
except ImportError as exc:
    errors.append('Pillow / ImageCms: ' + str(exc))
if errors:
    print('\n'.join(errors), file=sys.stderr)
    sys.exit(1)
print('Dependensi siap.')
CHECK_PY
    if (( check_only )); then
        printf '\nPemeriksaan selesai; tidak ada file yang diubah.\n'
        exit 0
    fi
    printf '[3/3] Memasang aplikasi dan submenu...\n'
fi

/usr/bin/python3 - "$action" <<'INSTALL_PY'
"""Per-user install/uninstall with backup, atomic replacement, and rollback."""
import ast
import datetime
import json
import os
from pathlib import Path
import shlex
import shutil
import sys
import tempfile


def atomic_write(path, text, mode=0o644):
    path.parent.mkdir(parents=True, exist_ok=True)
    descriptor, name = tempfile.mkstemp(prefix='.img2avif-install-', dir=path.parent)
    try:
        with os.fdopen(descriptor, 'w') as stream:
            stream.write(text)
        os.chmod(name, mode)
        os.replace(name, path)
    finally:
        Path(name).unlink(missing_ok=True)


def manage(assets, action):
    data = Path(os.environ.get('XDG_DATA_HOME', Path.home() / '.local/share'))
    config = Path(os.environ.get('XDG_CONFIG_HOME', Path.home() / '.config')) / 'img2avif/config.json'
    launcher = Path.home() / '.local/bin/img2avif'
    converter = data / 'img2avif/convert.py'
    extension = data / 'nemo-python/extensions/nemo_img2avif.py'
    paths = {'convert.py': converter, 'nemo_img2avif.py': extension, 'img2avif': launcher, 'convert-image': launcher.with_name('convert-image')}
    if action not in ('install', 'uninstall'):
        raise ValueError('Aksi tidak dikenal: ' + action)
    if action == 'install':
        ast.parse(assets['convert.py'])
        ast.parse(assets['nemo_img2avif.py'])
        defaults = json.loads(assets['config.json'])
        assets = dict(assets, img2avif='#!/usr/bin/env bash\nexec /usr/bin/python3 ' + shlex.quote(str(converter)) + ' "$@"\n')
        assets['convert-image'] = assets['img2avif']
    backup = None
    for key, path in paths.items():
        if path.is_symlink():
            raise RuntimeError('Target berupa symlink; tidak diubah: ' + str(path))
        if path.exists():
            if not path.is_file():
                raise RuntimeError('Target bukan file: ' + str(path))
            if backup is None:
                root = data / 'img2avif-backups'
                root.mkdir(parents=True, exist_ok=True)
                backup = Path(tempfile.mkdtemp(prefix=datetime.datetime.now().strftime('%Y%m%d-%H%M%S-'), dir=root))
            shutil.copy2(path, backup / key)
    changed = []
    created_config = False
    try:
        for key, path in paths.items():
            if action == 'install':
                atomic_write(path, assets[key], 0o755 if key in ('img2avif', 'convert-image') else 0o644)
            else:
                path.unlink(missing_ok=True)
            changed.append((key, path))
        if action == 'install':
            config.parent.mkdir(parents=True, exist_ok=True)
            try:
                with config.open('x') as stream:
                    created_config = True
                    json.dump(defaults, stream, indent=2)
                    stream.write('\n')
            except FileExistsError:
                pass
    except BaseException:
        for key, path in reversed(changed):
            saved = backup / key if backup else None
            if saved and saved.exists():
                os.replace(saved, path)
            else:
                path.unlink(missing_ok=True)
        if created_config:
            config.unlink(missing_ok=True)
        raise
    if backup:
        print('Backup:', backup)
    if action == 'install':
        print('Menu terpasang: Convert Image > Avif / Jpg / Pdf / Png / Webp > High Quality / Standard / Small Size')
        print('Konfigurasi:', config)
        print('CLI:', launcher.with_name('convert-image'))
        print('Alias kompatibilitas:', launcher)
    else:
        print('Converter, launcher, dan menu dihapus.')
        print('Gambar, konfigurasi, log, dan backup tetap tersimpan.')


