               '            except FileExistsError:\n'
               '                continue\n'
               '            try:\n'
               '                with os.fdopen(descriptor, "wb") as output, encoded.open("rb") as '
               'data:\n'
               '                    shutil.copyfileobj(data, output)\n'
               '                return target\n'
               '            except BaseException:\n'
               '                target.unlink(missing_ok=True)\n'
               '                raise\n'
               '    raise RuntimeError("Terlalu banyak hasil dengan nama yang sama")\n'
               '\n'
               '\n'
               'def encode_pdf(image, encoded, mode, cfg, progress):\n'
               '    """One image per page, preserving aspect ratio with no margins or '
               'cropping."""\n'
               '    from reportlab.pdfgen.canvas import Canvas\n'
               '    from reportlab.lib.utils import ImageReader\n'
               '    from pypdf import PdfReader\n'
               '\n'
               '    progress.update("Encoding PDF")\n'
               '    jpeg = io.BytesIO()\n'
               '    image.save(jpeg, format="JPEG", quality=cfg["pdf_" + mode + "_quality"],\n'
               '               subsampling=0 if mode == "high" else 2, optimize=True, '
               'progressive=True)\n'
               '    jpeg.seek(0)\n'
               '    progress.check()\n'
               '    # Nominal 96 dpi; keep unusually wide/tall pages within the PDF page limit.\n'
               '    scale = min(72 / 96, 14400 / max(image.size))\n'
               '    width, height = (edge * scale for edge in image.size)\n'
               '    canvas = Canvas(str(encoded), pagesize=(width, height), pageCompression=1, '
               'invariant=1)\n'
               '    canvas.setTitle("Converted image")\n'
               '    canvas.drawImage(ImageReader(jpeg), 0, 0, width=width, height=height)\n'
               '    canvas.showPage()\n'
               '    canvas.save()\n'
               '    progress.check()\n'
               '    with encoded.open("rb") as stream:\n'
               '        reader = PdfReader(stream, strict=True)\n'
               '        if len(reader.pages) != 1:\n'
               '            raise RuntimeError("Verifikasi PDF gagal: jumlah halaman")\n'
               '        page = reader.pages[0]\n'
               '        if abs(float(page.mediabox.width) - width) > 0.01 or '
               'abs(float(page.mediabox.height) - height) > 0.01:\n'
               '            raise RuntimeError("Verifikasi PDF gagal: ukuran halaman")\n'
               '        objects = page["/Resources"]["/XObject"].get_object()\n'
               '        images = [obj.get_object() for obj in objects.values() if '
               'obj.get_object().get("/Subtype") == "/Image"]\n'
               '        if len(images) != 1 or (images[0]["/Width"], images[0]["/Height"]) != '
               'image.size:\n'
               '            raise RuntimeError("Verifikasi PDF gagal: dimensi gambar")\n'
               '        with Image.open(io.BytesIO(images[0].get_data())) as check:\n'
               '            check.load()\n'
               '            if check.size != image.size:\n'
               '                raise RuntimeError("Verifikasi PDF gagal: decode gambar")\n'
               '\n'
               '\n'
               'def convert(source, mode, cfg, modern, progress, log, output_format="avif"):\n'
               '    if output_format not in ("avif", "jpg", "pdf", "png", "webp"):\n'
               '        raise ValueError("Format output tidak didukung")\n'
               '    if source.suffix.lower() not in EXTENSIONS or not source.is_file():\n'
               '        raise ValueError("File tidak didukung atau tidak ditemukan")\n'
               '    with tempfile.TemporaryDirectory(prefix=".img2avif-", dir=source.parent) as '
               'scratch:\n'
               '        temp = Path(scratch)\n'
               '        input_source = source\n'
               '        if source.suffix.lower() == ".avif":\n'
               '            # Use libavif even on systems whose Pillow has no AVIF plugin.\n'
               '            info = temp / "avif-info.txt"\n'
               '            with info.open("w", encoding="utf-8") as metadata:\n'
               '                run(["avifdec", "--info", str(source)], progress, metadata)\n'
               '            report = info.read_text(encoding="utf-8", errors="replace")\n'
               '            log.write(report)\n'
               '            frames = re.findall(r"^\\s*\\*\\s+\\d+ timescales per '
               'second.*?,\\s*(\\d+) frames?\\s*$", report, re.MULTILINE)\n'
               '            depth = re.findall(r"^\\s*\\*\\s+Bit Depth\\s*:\\s*(\\d+)\\s*$", '
               'report, re.MULTILINE)\n'
               '            if not frames or not depth:\n'
               '                raise ValueError("Tidak dapat memverifikasi metadata AVIF")\n'
               '            if int(frames[-1]) != 1:\n'
               '                raise ValueError("Animasi AVIF dilewati; skrip ini untuk gambar '
               'diam")\n'
               '            if int(depth[-1]) > 8 and mode == "high" and output_format in ("avif", '
               '"png", "webp"):\n'
               '                raise ValueError("AVIF di atas 8-bit dilewati pada High Quality '
               'lossless")\n'
               '            input_source = temp / "decoded-input.png"\n'
               '            run(["avifdec", "--depth", "8", str(source), str(input_source)], '
               'progress, log)\n'
               '        image = prepare(input_source, mode, cfg, output_format)\n'
               '        png, encoded, decoded = temp / "input.png", temp / ("output." + '
               'output_format), temp / "check.png"\n'
               '        if output_format in ("png", "webp"):\n'
               '            progress.update("Encoding " + output_format.upper() + ": " + '
               'source.name)\n'
               '            if output_format == "png":\n'
               '                image.save(encoded, format="PNG", optimize=True, '
               'compress_level=9)\n'
               '            else:\n'
               '                if max(image.size) > 16383:\n'
               '                    raise ValueError("WebP maksimum 16383 piksel per sisi; pilih '
               'Standard atau Small Size")\n'
               '                image.save(encoded, format="WEBP", lossless=mode == "high",\n'
               '                           quality=100 if mode == "high" else cfg["webp_" + mode + '
               '"_quality"],\n'
               '                           method=6, exact=True, '
               'icc_profile=image.info.get("icc_profile", b""))\n'
               '            progress.check()\n'
               '            with Image.open(encoded) as check:\n'
               '                check.load()\n'
               '                if check.format != output_format.upper() or check.size != '
               'image.size:\n'
               '                    raise RuntimeError("Verifikasi format/dimensi gagal")\n'
               '                if (output_format == "png" or mode == "high") and '
               'check.convert("RGBA").tobytes() != image.convert("RGBA").tobytes():\n'
               '                    raise RuntimeError("Verifikasi lossless gagal: piksel berubah; '
               'hasil tidak disimpan")\n'
               '            progress.check()\n'
               '            return publish(encoded, source, mode, output_format), image.size\n'
               '        if output_format in ("jpg", "pdf"):\n'
               '            # JPEG has no alpha channel; composite on white instead of discarding '
               'alpha.\n'
               '            profile = image.info.get("icc_profile")\n'
               '            if image.mode == "RGBA":\n'
               '                background = Image.new("RGB", image.size, "white")\n'
               '                background.paste(image, mask=image.getchannel("A"))\n'
               '                image = background\n'
               '            else:\n'
               '                image = image.convert("RGB")\n'
               '            if output_format == "pdf":\n'
               '                # PDF DeviceRGB uses sRGB pixels rather than an untagged source '
               'profile.\n'
               '                if profile:\n'
               '                    srgb = ImageCms.createProfile("sRGB")\n'
               '                    image = ImageCms.profileToProfile(image, '
               'ImageCms.ImageCmsProfile(io.BytesIO(profile)), srgb, outputMode="RGB")\n'
               '                encode_pdf(image, encoded, mode, cfg, progress)\n'
               '                progress.check()\n'
               '                return publish(encoded, source, mode, output_format), image.size\n'
               '            progress.update("Encoding JPG: " + source.name)\n'
               '            image.save(encoded, format="JPEG", quality=cfg["jpg_" + mode + '
               '"_quality"],\n'
               '                       subsampling=0 if mode == "high" else 2, optimize=True,\n'
               '                       progressive=True, icc_profile=profile)\n'
               '            progress.check()\n'
               '            with Image.open(encoded) as check:\n'
               '                check.load()\n'
               '                if check.format != "JPEG" or check.size != image.size:\n'
               '                    raise RuntimeError("Verifikasi JPG gagal")\n'
               '            target = publish(encoded, source, mode, output_format)\n'
               '            return target, image.size\n'
               '        image.save(png, format="PNG", compress_level=1)\n'
               '        run(encoder_args(mode, cfg, modern) + [str(png), str(encoded)], progress, '
               'log)\n'
               '        if not encoded.is_file() or not encoded.stat().st_size:\n'
               '            raise RuntimeError("Encoder tidak menghasilkan AVIF")\n'
               '        progress.update("Memeriksa hasil: " + source.name)\n'
               '        run(["avifdec", str(encoded), str(decoded)], progress, log)\n'
               '        with Image.open(decoded) as check:\n'
               '            if check.size != image.size:\n'
               '                raise RuntimeError("Verifikasi dimensi gagal")\n'
               '            if mode == "high" and check.convert("RGBA").tobytes() != '
               'image.convert("RGBA").tobytes():\n'
               '                raise RuntimeError("Verifikasi lossless gagal: piksel berubah; '
               'hasil tidak disimpan")\n'
               '        progress.check()\n'
               '        target = publish(encoded, source, mode)\n'
               '    return target, image.size\n'
               '\n'
               '\n'
               'def main():\n'
               '    if windows():\n'
               '        for stream in (sys.stdout, sys.stderr):\n'
               '            if stream is not None and hasattr(stream, "reconfigure"):\n'
               '                stream.reconfigure(encoding="utf-8", errors="replace")\n'
               '    if len(sys.argv) == 3 and sys.argv[1] == "--request":\n'
               '        request = Path(sys.argv[2])\n'
               '        try:\n'
               '            payload = json.loads(request.read_text(encoding="utf-8"))\n'
               '            if not isinstance(payload.get("files"), list) or not payload["files"] '
               'or not all(isinstance(p, str) for p in payload["files"]):\n'
               '                raise ValueError("Daftar gambar tidak valid")\n'
               '            options = ["--no-gui"] if payload.get("no_gui") is True else []\n'
               '            sys.argv[1:] = ["--format", payload.get("format", "avif"), '
               'payload["mode"], *options, "--", *payload["files"]]\n'
               '        finally:\n'
               '            request.unlink(missing_ok=True)\n'
               '    parser = argparse.ArgumentParser(description="Convert Image untuk Linux dan '
               'Windows")\n'
               '    parser.add_argument("--format", choices=("avif", "jpg", "pdf", "png", "webp"), '
               'default="avif", dest="output_format")\n'
               '    parser.add_argument("mode", choices=MODES)\n'
               '    parser.add_argument("--no-gui", action="store_true")\n'
               '    parser.add_argument("files", nargs="+")\n'
               '    args = parser.parse_args()\n'
               '    progress = None\n'
               '    try:\n'
               '        required = (["avifenc", "avifdec"] if args.output_format == "avif" else '
               '[]) + ([] if args.no_gui or windows() else ["zenity"])\n'
               '        if any(Path(filename).suffix.lower() == ".avif" for filename in '
               'args.files) and "avifdec" not in required:\n'
               '            required.append("avifdec")\n'
               '        for tool in required:\n'
               '            if not find_tool(tool):\n'
               '                raise RuntimeError("Program belum terpasang: " + tool)\n'
               '        if args.output_format == "pdf":\n'
               '            try:\n'
               '                import reportlab\n'
               '                import pypdf\n'
               '            except ImportError as exc:\n'
               '                raise RuntimeError("Dependensi PDF belum tersedia; jalankan ulang '
               'installer: " + str(exc))\n'
               '        cfg = settings()\n'
               '        modern = False\n'
               '        if args.output_format == "avif":\n'
               '            probe = subprocess.run([find_tool("avifenc"), "--help"], '
               'capture_output=True, text=True,\n'
               '                                   encoding="utf-8", errors="replace", check=True, '
               '**process_options())\n'
               '            modern = "--qcolor" in probe.stdout + probe.stderr\n'
               '        cache = user_directory("cache")\n'
               '        cache.mkdir(parents=True, exist_ok=True)\n'
               '        descriptor, name = tempfile.mkstemp(prefix="convert-", suffix=".log", '
               'dir=cache)\n'
               '        logpath = Path(name)\n'
               '        done, errors, total_in, total_out = [], [], 0, 0\n'
               '        cancelled = False\n'
               '        progress = Progress(args.mode, len(args.files), args.no_gui, '
               'args.output_format)\n'
               '        with os.fdopen(descriptor, "w", encoding="utf-8") as log:\n'
               '            for number, filename in enumerate(args.files, 1):\n'
               '                source = Path(os.path.abspath(filename))\n'
               '                try:\n'
               '                    progress.update("{}/{} — {} (mohon tunggu)".format(number, '
               'len(args.files), source.name))\n'
               '                    before = source.stat().st_size\n'
               '                    target, size = convert(source, args.mode, cfg, modern, '
               'progress, log, args.output_format)\n'
               '                    after = target.stat().st_size\n'
               '                    total_in += before\n'
               '                    total_out += after\n'
               '                    line = "{} → {} | {}×{} | {} → {} byte".format(source.name, '
               'target.name, *size, before, after)\n'
               '                    done.append(line)\n'
               '                    log.write("OK " + line + "\\n")\n'
               '                except Cancelled:\n'
               '                    cancelled = True\n'
               '                    log.write("DIBATALKAN\\n")\n'
               '                    break\n'
               '                except Exception as exc:\n'
