               '        return 1\n'
               '    finally:\n'
               '        if progress:\n'
               '            progress.close()\n'
               '\n'
               '\n'
               'if __name__ == "__main__":\n'
               '    def stop(_signum, _frame):\n'
               '        raise Cancelled()\n'
               '    signal.signal(signal.SIGTERM, stop)\n'
               '    signal.signal(signal.SIGINT, stop)\n'
               '    raise SystemExit(main())\n',
 'nemo_img2avif.py': '"""Nemo context submenu. Encoding runs outside the file-manager process."""\n'
                     'import json\n'
                     'import os\n'
                     'from pathlib import Path\n'
                     'import subprocess\n'
                     'import tempfile\n'
