                     '\n'
                     '\n'
                     'class Img2AvifMenu(GObject.GObject, Nemo.MenuProvider):\n'
                     '    def get_file_items(self, window, files):\n'
                     '        if not files:\n'
                     '            return []\n'
                     '        paths = []\n'
                     '        for item in files:\n'
                     '            path = Gio.File.new_for_uri(item.get_uri()).get_path()\n'
                     '            if item.is_directory() or not path or Path(path).suffix.lower() '
                     'not in (".jpg", ".jpeg", ".png", ".webp", ".avif"):\n'
                     '                return []\n'
                     '            paths.append(path)\n'
                     '        root = Nemo.MenuItem(name="ConvertImage::Root", label="Convert '
                     'Image", tip="Konversi gambar ke AVIF, JPG, PDF, PNG, atau WebP", '
                     'icon="image-x-generic")\n'
                     '        menu = Nemo.Menu()\n'
                     '        for output_format, format_label in (("avif", "Avif"), ("jpg", '
                     '"Jpg"), ("pdf", "Pdf"), ("png", "Png"), ("webp", "Webp")):\n'
                     '            format_item = Nemo.MenuItem(name="ConvertImage::" + '
                     'output_format, label=format_label, tip="Konversi ke " + format_label)\n'
                     '            presets = Nemo.Menu()\n'
                     '            tips = {\n'
                     '                "avif": ("Lossless 8-bit, resolusi asli; hasil '
                     'diverifikasi",\n'
                     '                         "Maks. 1920 px, kualitas AVIF 60", "Maks. 1280 px, '
                     'kualitas AVIF 40"),\n'
                     '                "jpg": ("Resolusi asli, kualitas JPG 95 (lossy)",\n'
                     '                        "Maks. 1920 px, kualitas JPG 85", "Maks. 1280 px, '
                     'kualitas JPG 70"),\n'
                     '                "pdf": ("Satu gambar per PDF, resolusi asli, kualitas 95",\n'
                     '                        "Satu gambar per PDF, maks. 1920 px, kualitas 85", '
                     '"Satu gambar per PDF, maks. 1280 px, kualitas 70"),\n'
                     '                "png": ("Lossless 8-bit, resolusi asli", "Lossless setelah '
                     'resize, maks. 1920 px", "Lossless setelah resize, maks. 1280 px"),\n'
                     '                "webp": ("Lossless 8-bit, resolusi asli", "Maks. 1920 px, '
                     'kualitas WebP 80", "Maks. 1280 px, kualitas WebP 60"),\n'
                     '            }\n'
                     '            for (mode, label), tip in zip((("high", "High Quality"), '
