                     '                presets.append_item(child)\n'
                     '            format_item.set_submenu(presets)\n'
                     '            menu.append_item(format_item)\n'
                     '        root.set_submenu(menu)\n'
                     '        return [root]\n'
                     '\n'
                     '    def activate(self, _item, output_format, mode, paths):\n'
                     '        data = Path(os.environ.get("XDG_DATA_HOME", Path.home() / '
                     '".local/share"))\n'
                     '        script = data / "img2avif/convert.py"\n'
                     '        # Request file avoids ARG_MAX even for thousands of selected '
